import{_ as t,o as s,c as i,a4 as o}from"./chunks/framework.BE47AOxC.js";const m=JSON.parse(`{"title":"ADR-0047 — Un front de démarrage par usage, optionnel et client de l'API publique","description":"Extrait de docs/adr/0047-front-de-demarrage-optionnel.md, publié tel quel à chaque construction du site.","frontmatter":{"title":"ADR-0047 — Un front de démarrage par usage, optionnel et client de l'API publique","description":"Extrait de docs/adr/0047-front-de-demarrage-optionnel.md, publié tel quel à chaque construction du site."},"headers":[],"relativePath":"developpeurs/adr/0047-front-de-demarrage-optionnel.md","filePath":"developpeurs/adr/0047-front-de-demarrage-optionnel.md"}`),n={name:"developpeurs/adr/0047-front-de-demarrage-optionnel.md"};function r(a,e,l,u,d,c){return s(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="adr-0047--un-front-de-démarrage-par-usage-optionnel-et-client-de-lapi-publique" tabindex="-1">ADR-0047 — Un front de démarrage par usage, optionnel et client de l&#39;API publique <a class="header-anchor" href="#adr-0047--un-front-de-démarrage-par-usage-optionnel-et-client-de-lapi-publique" aria-label="Permalink to &quot;ADR-0047 — Un front de démarrage par usage, optionnel et client de l&#39;API publique {#adr-0047--un-front-de-démarrage-par-usage-optionnel-et-client-de-lapi-publique}&quot;">​</a></h1><p><strong>Date :</strong> 24 septembre 2026 <strong>Statut :</strong> Accepté <strong>Décideur :</strong> Sébastien Rapuzzi (Product Owner) <strong>Source :</strong> plan de déploiement du 24/09/2026, décisions D2 et D5 ; complète l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0034-adresses-publiques">ADR-0034</a> et l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0035-plan-de-site-flux-et-robots">ADR-0035</a>, qui décrivent un Core « headless » dont le site public est produit par un front tiers ; s&#39;appuie sur l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0046-profils-d-usage-a-l-installation">ADR-0046</a><strong>Renvois ultérieurs :</strong> décisions n°3 (personnalisation) et n°4 (accessibilité) précisées par l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0049-identite-visuelle-du-site-public">ADR-0049</a> (24 septembre 2026 : identité visuelle du site public).</p><h2 id="contexte" tabindex="-1">Contexte <a class="header-anchor" href="#contexte" aria-label="Permalink to &quot;Contexte {#contexte}&quot;">​</a></h2><p>Le Core est headless : l&#39;API sert ce dont un front a besoin, et chaque site le rend à sa façon. Ce dépôt ne livrait donc aucun site public. Pour une collectivité qui paie un prestataire, c&#39;est un choix d&#39;architecture sain.</p><p>Pour un référent qui installe un blog ou un portfolio sans développeur, c&#39;est une impasse. Il obtient un back-office où rédiger, mais rien que ses lecteurs puissent voir. Drupal, qui sert de modèle au Product Owner, installe un site avec un thème.</p><p>Le Product Owner a tranché : Teuthis livre un site public prêt à l&#39;emploi pour chaque usage.</p><h2 id="décision" tabindex="-1">Décision <a class="header-anchor" href="#décision" aria-label="Permalink to &quot;Décision {#décision}&quot;">​</a></h2><p><strong>1. Le Core reste headless. Le dépôt livre en plus une application <code>apps/front</code> (Nuxt, rendu côté serveur), cliente de l&#39;API publique comme n&#39;importe quel front tiers.</strong></p><ul><li>Le front n&#39;utilise <strong>aucune route privée</strong>, et aucune capacité qu&#39;un front tiers n&#39;aurait pas.</li><li>S&#39;il lui manque quelque chose, on l&#39;ajoute à l&#39;API publique, pour tous les fronts.</li><li>Le Core ne dépend jamais du front.</li><li>Le profil « Sur mesure (headless) » s&#39;installe sans lui.</li></ul><p><strong>2. Un socle commun, puis un thème par profil (D2).</strong> Le socle couvre :</p><ul><li>la résolution d&#39;adresse (<code>/public/resolve</code>) et le rendu des blocs du Page Builder ;</li><li>les vues liste et la recherche ;</li><li>les formulaires publics, avec relecture et captcha ;</li><li>le relais de <code>robots.txt</code>, du plan de site et des flux (ADR-0035) ;</li><li>le bandeau cookies, le multilingue, les pages d&#39;erreur et le mode maintenance.</li></ul><p>Les thèmes suivent cet ordre :</p><ol><li><strong>Blog et presse</strong> : la plus petite surface, qui valide toute la chaîne ;</li><li><strong>Collectivité</strong> : la plus riche, et le marché premier ;</li><li><strong>Portfolio</strong> ;</li><li><strong>Catalogue et devis</strong>.</li></ol><p><strong>3. La personnalisation se fait sans code, depuis le back-office</strong>, dans les réglages du site : logo, couleurs, polices et pied de page. <strong>Le contraste est vérifié à l&#39;enregistrement</strong> : une combinaison de couleurs qui ferait échouer le RGAA est refusée, avec son explication.</p><p><strong>4. L&#39;accessibilité RGAA AA est visée dès le socle.</strong> Une vérification automatique (axe) tourne en CI, et chaque thème reçoit une revue manuelle. <strong>On n&#39;affirme aucune conformité</strong> tant qu&#39;un audit n&#39;a pas été fait.</p><p><strong>5. Les menus découlent de l&#39;arbre des pages (D5)</strong>, par le plugin Navigation déjà livré. L&#39;API n&#39;a pas d&#39;entité menu. Un Epic « menus » n&#39;est lancé que si un thème bute réellement dessus : lien externe dans le menu, pied de page distinct de l&#39;arbre.</p><h2 id="alternatives-considérées" tabindex="-1">Alternatives considérées <a class="header-anchor" href="#alternatives-considérées" aria-label="Permalink to &quot;Alternatives considérées {#alternatives-considérées}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Pourquoi écartée</th></tr></thead><tbody><tr><td>Rester headless, et orienter vers des fronts d&#39;exemple</td><td>Un non-développeur n&#39;obtient rien de visible. C&#39;est l&#39;objectif même du plan qui tombe.</td></tr><tr><td>Commencer par le thème Collectivité</td><td>Le socle se validerait sur le thème le plus lourd : 25 extensions, démarches, annuaires. Le risque de retard est plus grand.</td></tr><tr><td>Un seul thème générique pour les quatre profils</td><td>Tout le monde a vite un site, mais aucun n&#39;est adapté à son usage.</td></tr><tr><td>Un Epic « menus » dès le socle</td><td>Une semaine de plus avant tout site visible, pour un besoin que l&#39;arbre des pages couvre peut-être.</td></tr></tbody></table><h2 id="conséquences" tabindex="-1">Conséquences <a class="header-anchor" href="#conséquences" aria-label="Permalink to &quot;Conséquences {#conséquences}&quot;">​</a></h2><p><strong>Positives</strong></p><ul><li>Le « headless » est éprouvé par le dépôt lui-même. Tout manque de l&#39;API publique apparaît en construisant le front, et se comble pour tous les fronts.</li><li>Un exploitant a un site public dès l&#39;installation.</li></ul><p><strong>Négatives</strong></p><ul><li>C&#39;est le chantier le plus long du plan. Il est repoussé au second jalon, pour que le déploiement et les profils n&#39;attendent pas.</li><li>Une troisième application à maintenir, avec ses dépendances et son image.</li><li>Les premiers exploitants d&#39;un thème non encore livré n&#39;ont pas de site public. L&#39;installateur le leur dit.</li></ul><h2 id="actions-liées" tabindex="-1">Actions liées <a class="header-anchor" href="#actions-liées" aria-label="Permalink to &quot;Actions liées {#actions-liées}&quot;">​</a></h2><ul><li>[x] Socle du front : <code>apps/front</code>, rendu des blocs, listes, recherche, formulaires, fichiers SEO, cookies, multilingue, personnalisation avec contrôle du contraste, axe en CI, image <code>teuthis-front</code>. <strong>Fait le 01/10/2026</strong> — <code>apps/front</code> (Nuxt 3 SSR, client de la seule API publique, <code>/public/site</code> pour trouver le site par son hôte et <code>/public/resolve</code> pour chaque adresse, ADR-0064) : rendu des blocs (repli pour un type inconnu), listes paginées, recherche, formulaire avec relecture et captcha Altcha servi par le front, <code>robots.txt</code> / plan de site / flux relayés, bandeau cookies, multilingue, pages 404/410/503/500, thème du site en rôles de couleur dont l&#39;API a vérifié le contraste ; HTML des champs riches assaini côté serveur par liste blanche ; aucun tiers contacté (polices système, CSP <code>&#39;self&#39;</code>, intégrations rendues en liens) ; images d&#39;origine avec <code>width</code>/<code>height</code> et <code>loading=&quot;lazy&quot;</code> (déclinaisons reportées). Tests : 38 tests vitest, axe sans violation sur 8 pages × 3 largeurs (<code>npm run test:a11y</code>, job <code>front</code> de la CI), image <code>teuthis-front</code> non root en lecture seule, service <code>cms-front</code> (profil Compose <code>front</code>), gabarit Caddy <code>www.caddy</code>, publication signée. <strong>Manques connus</strong> : filtres de liste et facettes non rendus, pièces jointes de formulaire non saisissables, menu tiré des seules pages de premier niveau de <code>/sitemap</code>. L&#39;automatisation axe ne vaut pas conformité RGAA : l&#39;audit manuel reste à faire.</li><li>[x] Thème « Blog et presse ». <strong>Fait le 01/10/2026</strong> — <code>apps/front/themes/blog-presse/</code> (accueil, liste d&#39;articles, fiche avec voisines, recherche, contact), choisi par <code>NUXT_PUBLIC_THEME</code> ; l&#39;installateur le met en service pour le profil <code>blog_presse</code> (<code>--domaine-site</code>, DNS contrôlé, signature et empreinte de <code>teuthis-front</code> vérifiées, santé de <code>cms-front</code> attendue), 135 tests bats. Le profil <code>blog_presse</code> n&#39;installe pas de formulaire <code>contact</code> : le lien est alors masqué.</li><li>[x] Thème « Collectivité ». <strong>Fait le 08/10/2026</strong> (lot 14, issue #9) — <code>apps/front/themes/collectivite/</code> : accueil de commune (flash info en tête, accès rapides aux démarches, actualités, prochains événements), agenda (dates en <code>&lt;time&gt;</code>, lieu, à venir et passés), annuaire des lieux et des élus, démarches, gabarits génériques ; l&#39;installateur le pose pour le profil Collectivité (<code>theme_front_pour</code>). Preuve : <code>npm run test:a11y</code>, 19 pages Collectivité aux trois largeurs sans violation axe ni défaut adaptatif, <code>tests/unitaires/collectivite.test.ts</code>. Audit manuel RGAA non fait.</li><li>[ ] Thème « Portfolio ».</li><li>[ ] Thème « Catalogue et devis ».</li><li>[ ] Recette réelle : un référent non développeur par profil, sur un serveur jetable, sans aide, jusqu&#39;au critère du plan (moins de 15 minutes, sans éditer de fichier).</li><li>[ ] <em>(Conditionnelle)</em> Epic « menus », si un thème bute sur l&#39;arbre des pages.</li></ul>',25)])])}const g=t(n,[["render",r]]);export{m as __pageData,g as default};
